head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00018";
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — usrTpCd, spotIsuTrdMktTpCd, corpUsrTpCd, preKonex

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "img_24", attr: "src", fn: function () { return "/img/submission/corpfind/" + String((dma_pageContext.get("titleImageName") ?? "")) + ".gif"; } },
        { childId: "iframe_141", attr: "src", fn: function () { return "/submission/corpList.do?method=searchCorpList&marketType=" + String((dma_pageContext.get("marketType") ?? "")); } },
        { childId: "iframe_145", attr: "src", fn: function () { return "/submission/corpList.do?method=searchCorpList&marketType=" + String((dma_pageContext.get("marketType") ?? "")) + "&voteYN=" + String((dma_pageContext.get("voteYN") ?? "")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_65", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "")==='1' || (dma_pageContext.get("usrTpCd") ?? "")==='2'); } }, { id: "c_otherwise_80", fn: function(){ return (!(((dma_pageContext.get("usrTpCd") ?? "")==='1' || (dma_pageContext.get("usrTpCd") ?? "")==='2'))); } }, { id: "ipt_marketType_5", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='1'); } }, { id: "ipt_marketType_6", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='2'); } }, { id: "ipt_marketType_7", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='6'); } }, { id: "c_otherwise_91", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='1') || ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='2') || ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='6'))); } }, { id: "c_when_83", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "")==='3' && (dma_pageContext.get("corpUsrTpCd") ?? "") === '31'); } }, { id: "c_otherwise_93", fn: function(){ return (!(((dma_pageContext.get("usrTpCd") ?? "")==='3' && (dma_pageContext.get("corpUsrTpCd") ?? "") === '31'))); } }, { id: "c_when_134", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='1'); } }, { id: "c_when_136", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='2'); } }, { id: "c_when_138", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='6'); } }, { id: "c_otherwise_140", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='1') || ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='2') || ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "")==='6'))); } }, { id: "c_when_132", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "")==='3' && (dma_pageContext.get("corpUsrTpCd") ?? "") === '31'); } }, { id: "c_when_142", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "")==='3' && (dma_pageContext.get("corpUsrTpCd") ?? "") === '62' && (dma_pageContext.get("preKonex") ?? "")==='Y'); } }, { id: "c_otherwise_144", fn: function(){ return (!(((dma_pageContext.get("usrTpCd") ?? "")==='3' && (dma_pageContext.get("corpUsrTpCd") ?? "") === '31') || ((dma_pageContext.get("usrTpCd") ?? "")==='3' && (dma_pageContext.get("corpUsrTpCd") ?? "") === '62' && (dma_pageContext.get("preKonex") ?? "")==='Y'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00018' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00018' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00018' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00018.onpageload' });
    }
};

