///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchCorpList
 * @description search Corp List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpList = async function () {
    const sbmOptions = {
        id: "tx_searchCorpList",
        method: "post",
        action: "/submission/corpList.do?method=searchCorpList&marketType=stockMkt",
        ref: "dma_searchCorpListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/submission/corpList.do?method=searchCorpList&marketType=stockMkt",
        ref: "dma_searchCorpListByBeginIndexReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_6_ipt_corpname
 * @description on enter 6 ipt corpname 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_6_ipt_corpname = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchCorpList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00018.__on_enter_6_ipt_corpName' }); }
};

/**
 * @method
 * @name searchCorpList
 * @description search Corp List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpList = async function () {
    scwin.clearBtnImage();
    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "");
    (document.corpListForm || { elements: [] }).target = "iframe";
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchCorpList&marketType=stockMkt";
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchCorpList&marketType=" + dma_pageContext.get("marketType") + "&preKonex=Y";
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchCorpList&marketType=" + dma_pageContext.get("marketType") + "";
    await scwin.tx_searchCorpList();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchCorpList&marketType=stockMkt";
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchCorpList&marketType=" + dma_pageContext.get("marketType") + "&preKonex=Y";
    (document.corpListForm || { elements: [] }).action = "/submission/corpList.do?method=searchCorpList&marketType=" + dma_pageContext.get("marketType") + "";
    (document.corpListForm || { elements: [] }).target = "iframe";
    await scwin.tx_searchCorpListByBeginIndex();
};

