/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} comEngAbbrv comEngAbbrv
 * @param {String} eqtyoptIsuObjYn eqtyoptIsuObjYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, comEngAbbrv, eqtyoptIsuObjYn) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    str += "comEngAbbrv : " + comEngAbbrv + "\n";
    str += "eqtyoptIsuObjYn : " + eqtyoptIsuObjYn + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    try {
        scwin.frame.setCorpInfo(isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, comEngAbbrv, eqtyoptIsuObjYn, returnKey);
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00018' });
        scwin.frame.setCorpInfo(isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, returnKey);
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};

